// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract SecureMessageQueue {
    struct Message {
        bytes32 id;
        address sender;
        bytes payload;
        uint256 timestamp;
        bool processed;
    }

    struct FeatureFlags {
        bool enableBatching;
        bool enableEncryption;
        bool enableAuditLog;
        bool enablePurge;
    }

    address public owner;
    bytes32 private encryptionKey;
    mapping(uint256 => Message) private messageStore;
    mapping(address => bool) public authorizedConsumers;
    uint256 public messageCount;
    uint256 public processedCount;
    FeatureFlags public features;

    event MessageEnqueued(bytes32 indexed id, address sender);
    event MessageProcessed(bytes32 indexed id, address consumer);
    event MessagePurged(uint256 indexed index);
    event AuditEntry(address indexed actor, string action, bytes32 data);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedConsumers[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    constructor(bytes32 _encryptionKey) {
        owner = msg.sender;
        encryptionKey = _encryptionKey;
        features = FeatureFlags(true, true, true, true);
        authorizedConsumers[msg.sender] = true;
    }

    function setFeatureFlags(
        bool _batching,
        bool _encryption,
        bool _auditLog,
        bool _purge
    ) external onlyOwner {
        features = FeatureFlags(_batching, _encryption, _auditLog, _purge);
    }

    function rotateEncryptionKey(bytes32 _newKey) external onlyOwner {
        encryptionKey = _newKey;
        if (features.enableAuditLog) {
            emit AuditEntry(msg.sender, "KEY_ROTATED", bytes32(0));
        }
    }

    function addConsumer(address _consumer) external onlyOwner {
        authorizedConsumers[_consumer] = true;
    }

    function enqueue(bytes calldata _payload) external returns (bytes32) {
        bytes32 msgId = keccak256(abi.encodePacked(msg.sender, block.timestamp, messageCount));
        bytes memory finalPayload = _payload;

        if (features.enableEncryption) {
            finalPayload = _encryptPayload(_payload);
        }

        messageStore[messageCount] = Message({
            id: msgId,
            sender: msg.sender,
            payload: finalPayload,
            timestamp: block.timestamp,
            processed: false
        });

        messageCount++;
        emit MessageEnqueued(msgId, msg.sender);
        return msgId;
    }

    function consume(uint256 _index) external onlyAuthorized returns (bytes memory) {
        require(_index < messageCount, "Index out of bounds");
        Message storage msg_ = messageStore[_index];
        require(!msg_.processed, "Already processed");

        msg_.processed = true;
        processedCount++;

        bytes memory result = msg_.payload;
        if (features.enableEncryption) {
            result = _decryptPayload(msg_.payload);
        }

        if (features.enableAuditLog) {
            emit AuditEntry(msg.sender, "CONSUMED", msg_.id);
        }

        emit MessageProcessed(msg_.id, msg.sender);
        return result;
    }

    function batchConsume(uint256[] calldata _indices) external onlyAuthorized returns (bytes[] memory) {
        require(features.enableBatching, "Batching disabled");
        bytes[] memory results = new bytes[](_indices.length);

        for (uint256 i = 0; i < _indices.length; i++) {
            require(_indices[i] < messageCount, "Index out of bounds");
            Message storage msg_ = messageStore[_indices[i]];
            require(!msg_.processed, "Already processed");

            msg_.processed = true;
            processedCount++;

            if (features.enableEncryption) {
                results[i] = _decryptPayload(msg_.payload);
            } else {
                results[i] = msg_.payload;
            }

            emit MessageProcessed(msg_.id, msg.sender);
        }

        return results;
    }

    function purgeProcessed(uint256 _index) external onlyAuthorized {
        require(features.enablePurge, "Purge disabled");
        require(_index < messageCount, "Index out of bounds");
        require(messageStore[_index].processed, "Not yet processed");

        delete messageStore[_index];
        emit MessagePurged(_index);
    }

    function getQueueStatus() external view returns (
        uint256 total,
        uint256 processed,
        uint256 pending
    ) {
        return (messageCount, processedCount, messageCount - processedCount);
    }

    function _encryptPayload(bytes memory _data) internal view returns (bytes memory) {
        bytes memory encrypted = new bytes(_data.length);
        bytes32 key = encryptionKey;

        for (uint256 i = 0; i < _data.length; i++) {
            encrypted[i] = bytes1(uint8(_data[i]) ^ uint8(key[i % 32]));
        }

        return encrypted;
    }

    function _decryptPayload(bytes memory _data) internal view returns (bytes memory) {
        bytes memory decrypted = new bytes(_data.length);
        bytes32 key = encryptionKey;

        for (uint256 i = 0; i < _data.length; i++) {
            decrypted[i] = bytes1(uint8(_data[i]) ^ uint8(key[i % 32]));
        }

        return decrypted;
    }

    function getMessageMetadata(uint256 _index) external view onlyAuthorized returns (
        bytes32 id,
        address sender,
        uint256 timestamp,
        bool processed,
        uint256 payloadLength
    ) {
        require(_index < messageCount, "Index out of bounds");
        Message storage msg_ = messageStore[_index];
        return (msg_.id, msg_.sender, msg_.timestamp, msg_.processed, msg_.payload.length);
    }
}
